"""Build one common harness prefix; no benchmark JVM is launched."""
import argparse
import json
import os
from pathlib import Path
import shutil
import subprocess
import time

import runtime_identity as identity

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
JAVA = Path('/workspace/scratch/d0a0e51b9386/toolchain/jdk-25.0.5+8/bin')
MAIN_STEM = 'org/eclipse/rdf4j/sail/lmdb/benchmark/SharedSelectionExperiment'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--slot-released', action='store_true', required=True)
    args = parser.parse_args()
    provenance_path = HERE / 'prepared-harness-provenance.json'
    provenance = json.loads(provenance_path.read_text())
    provenance_sha = identity.sha(provenance_path)
    for path, expected in provenance['inputs'].items():
        assert identity.sha(path) == expected, 'Preserved source changed: ' + path
    for path, expected in provenance['generated'].items():
        assert identity.sha(HERE / path) == expected, 'Prepared source changed: ' + path
    for field in ('commonOriginalDescriptor', 'sharedOriginalRuntime', 'fixtureValidation'):
        assert identity.sha(provenance[field]) == provenance[field + 'Sha256']
    common = json.loads(Path(provenance['commonOriginalDescriptor']).read_text())
    shared = json.loads(Path(provenance['sharedOriginalRuntime']).read_text())
    assert identity.sha(common['classpathFile']) == common['classpathFileSha256']
    assert identity.sha(common['classpathManifestFile']) == common['classpathManifestSha256']
    old_check = json.loads(Path(provenance['fixtureValidation']).read_text())
    assert old_check['returncode'] == 0 and old_check['runtimeSha256'] == provenance['sharedOriginalRuntimeSha256']
    common_manifest = json.loads(Path(common['classpathManifestFile']).read_text())
    assert common_manifest[0] == common['harnessEntry']
    original_cp, original_manifest = identity.original_identity()
    assert len(common_manifest) == len(shared['manifest']) == 128
    assert common_manifest[1:] == shared['manifest'][1:] == original_manifest
    for prefix in (common_manifest[0], shared['manifest'][0]):
        assert identity.classpath_manifest(prefix['path']) == [prefix], 'Prior harness bytes changed'
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    classes = output / 'classes'
    classes.mkdir()
    before_files = {}
    for prefix in (common_manifest[0], shared['manifest'][0]):
        files = identity.tree_files(prefix['path'])
        assert not before_files.keys() & files.keys(), 'Unintended class shadow between original harnesses'
        before_files.update(files)
        for name in files:
            target = classes / name
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(Path(prefix['path']) / name, target)
    compiled = output / 'compiled-shared-main'
    compiled.mkdir()
    compile_cp = common_manifest[0]['path'] + os.pathsep + shared['manifest'][0]['path'] + os.pathsep + original_cp
    argv = [str(JAVA / 'javac'), '-proc:none', '-encoding', 'UTF-8', '-cp', compile_cp,
            '-d', str(compiled), provenance['newlyCompiledSource']]
    identity.write_new(output / 'compile-command.json', {'argv': argv, 'cwd': str(ROOT),
                                                        'startedEpochNs': time.time_ns()})
    with (output / 'compile.log').open('xb') as log:
        result = subprocess.run(argv, cwd=ROOT, stdout=log, stderr=subprocess.STDOUT, timeout=60)
    identity.write_new(output / 'compile-result.json', {'exitCode': result.returncode,
                                                       'finishedEpochNs': time.time_ns()})
    assert result.returncode == 0, 'Harness compilation failed; preserve output'
    new_files = identity.tree_files(compiled)
    assert new_files and all(name == MAIN_STEM + '.class' or name.startswith(MAIN_STEM + '$')
                             and name.endswith('.class') for name in new_files), 'Unexpected newly compiled class'
    assert new_files.keys() <= before_files.keys(), 'Unexpected class added to the harness'
    for name in new_files:
        shutil.copyfile(compiled / name, classes / name)
    final_files = identity.tree_files(classes)
    changed = identity.delta(before_files, final_files)
    assert not changed['added'] and not changed['removed']
    assert set(changed['changed']) <= set(new_files)
    assert all(final_files[name] == old for name, old in before_files.items() if name not in new_files)
    cp = str(classes) + os.pathsep + original_cp
    manifest = identity.classpath_manifest(cp)
    assert manifest[1:] == original_manifest and len(manifest) == 128
    (output / 'classpath.txt').write_text(cp + '\n')
    identity.write_new(output / 'classpath-manifest.json', manifest)
    identity.write_new(output / 'harness-class-files.json', final_files)
    descriptor = {'name': 'compact-page-common-original', 'diagnosticOnly': False,
        'sourceIdentity': identity.ORIGINAL_SOURCE + '+compact-page-harness-sha256-' + manifest[0]['sha256'],
        'productionSourceIdentity': identity.ORIGINAL_SOURCE,
        'classpathFile': str(output / 'classpath.txt'), 'classpathFileSha256': identity.sha(output / 'classpath.txt'),
        'classpathManifestFile': str(output / 'classpath-manifest.json'),
        'classpathManifestSha256': identity.sha(output / 'classpath-manifest.json'),
        'sourceProvenanceFile': str(provenance_path), 'sourceProvenanceSha256': provenance_sha,
        'harnessEntry': manifest[0], 'productionEntryIndex': 2, 'prefixEntryCount': 1,
        'originalEntriesUnchanged': 127, 'nativeEvaluation': True, 'directAdjacencyEnabled': True,
        'fixtures': ['fanout', 'shared-tail'], 'sharedOracleAndLaunchersUnchanged': True,
        'fanoutHarnessAndAdjacencyHelperUnchanged': True}
    identity.write_new(output / 'runtime-descriptor.json', descriptor)
    identity.write_new(output / 'build-summary.json', {'harnessFiles': len(final_files),
        'recompiledSharedMainFiles': sorted(new_files), 'changedClassFiles': changed,
        'unchangedCopiedClassFiles': sorted(set(before_files) - set(new_files)),
        'compilerOnlyNoBenchmarkJvm': True, 'sourceProvenanceSha256': provenance_sha,
        'compilerDriverSha256': identity.sha(Path(__file__))})
    assert identity.sha(provenance_path) == provenance_sha
    assert all(identity.sha(path) == expected for path, expected in provenance['inputs'].items())
    print(json.dumps({'runtimeDescriptor': str(output / 'runtime-descriptor.json'),
                      'original127EntriesUnchanged': True, 'harnessFiles': len(final_files),
                      'newlyCompiledFiles': len(new_files), 'benchmarkJvmsLaunched': 0}))


if __name__ == '__main__':
    main()
